 "content": "def transform(grid):
    """Extend horizontal and vertical center-lines from solid 3x3 color blocks.

    When different beams intersect, the crossing is left blank; all original
    nonzero input cells are preserved.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                # Avoid counting the same block at its other top-left corners.
                if r > 0 and all(grid[rr][c:c+3] == [color] * 3
                                 for rr in range(r - 1, r + 2)):
                    continue
                if c > 0 and all(grid[rr][cc] == color
                                 for rr in range(r, r + 3)
                                 for cc in range(c - 1, c + 2)):
                    continue
                blocks.append((r + 1, c + 1, color))

    # Each center axis carries its block's color across the grid. Different
    # colors meeting on a beam crossing cancel to background.
    beams = {}
    for cr, cc, color in blocks:
        for x in range(w):
            beams.setdefault((cr, x), set()).add(color)
        for y in range(h):
            beams.setdefault((y, cc), set()).add(color)
    for (r, c), colors in beams.items():
        if len(colors) == 1:
            out[r][c] = next(iter(colors))
        elif grid[r][c] == 0:
            out[r][c] = 0
    return out


